urlset:
{%- for entry in entries %}
    {%- set exclude_entry = false %}
    {%- if entry.extra %}
        {%- set exclude_entry = entry.extra.noindex | default(value=false) or entry.extra.exclude_from_sitemap | default(value=false) %}
    {%- endif %}
    {%- if not exclude_entry %}

    {{ entry.permalink | safe }}
    {%- if entry.updated %}
    {{ entry.updated }}
    {%- endif %}

    {%- endif %}
{%- endfor %}
